import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int n = Integer.parseInt(line.trim());int[] luckyNumbers = {4, 7, 44, 47, 74, 77, 444, 447, 474, 477, 744, 747, 774, 777};boolean isAlmostLucky = false;for (int lucky : luckyNumbers) {if (n % lucky == 0) {isAlmostLucky = true;break;}}if (isAlmostLucky) {System.out.println("YES");} else {System.out.println("NO");}}}